82. function* fetchReviews({
83.   payload: { errorHandlerId, addonSlug, page, score },
84. }: FetchReviewsAction): Saga {
85.   const errorHandler = createErrorHandler(errorHandlerId);
86. 
87.   try {
88.     yield put(errorHandler.createClearingAction());
89.     const state = yield select(getState);
90. 
91.     const params: GetReviewsParams = {
92.       addon: addonSlug,
93.       apiState: state.api,
94.       page,
95.       score: score || undefined,
96.     };
97. 
98.     const response: GetReviewsApiResponse = yield call(getReviews, params);
99. 
100.     yield put(
101.       setAddonReviews({
102.         addonSlug,
103.         page: page || '1',
104.         pageSize: response.page_size,
105.         reviewCount: response.count,
106.         reviews: response.results,
107.         score,
108.       }),
109.     );
110.   } catch (error) {
111.     log.warn(`Failed to load reviews for add-on slug ${addonSlug}: ${error}`);
112.     yield put(errorHandler.createErrorAction(error));
113.   }
114. }
115. 
116. function* fetchReviewPermissions({
117.   payload: { errorHandlerId, addonId, userId },
118. }: FetchReviewPermissionsAction): Saga {
119.   const errorHandler = createErrorHandler(errorHandlerId);
120. 
121.   try {
122.     yield put(errorHandler.createClearingAction());
123.     const state: AppState = yield select(getState);
124. 
125.     const params: GetReviewsParams = {
126.       addon: addonId,
127.       apiState: state.api,
128.       show_permissions_for: userId,
129.     };
130. 
131.     const response: GetReviewsApiResponse = yield call(getReviews, params);
132.     invariant(
133.       response.can_reply !== undefined,
134.       'response.can_reply was unexpectedly undefined',
135.     );
136. 
137.     yield put(
138.       setReviewPermissions({
139.         addonId,
140.         canReplyToReviews: response.can_reply,
141.         userId,
142.       }),
143.     );
144.   } catch (error) {
145.     log.warn(
146.       `Failed to load review permissions for add-on ID ${addonId}, user ID ${userId}: ${error}`,
147.     );
148.     yield put(errorHandler.createErrorAction(error));
149.   }
150. }
151. 
152. function* fetchUserReviews({
153.   payload: { errorHandlerId, page, userId },
154. }: FetchUserReviewsAction): Saga {
155.   const errorHandler = createErrorHandler(errorHandlerId);
156. 
157.   try {
158.     const state = yield select(getState);
159. 
160.     const params: GetReviewsParams = {
161.       apiState: state.api,
162.       page,
163.       user: userId,
164.     };
165. 
166.     const response: GetReviewsApiResponse = yield call(getReviews, params);
167. 
168.     yield put(
169.       setUserReviews({
170.         pageSize: response.page_size,
171.         reviewCount: response.count,
172.         reviews: response.results,
173.         userId,
174.       }),
175.     );
176.   } catch (error) {
177.     log.warn(`Failed to load reviews for user ID ${userId}: ${error}`);
178.     yield put(errorHandler.createErrorAction(error));
179.   }
180. }
181. 
182. function* handleReplyToReview({
183.   payload: { errorHandlerId, originalReviewId, body, title },
184. }: SendReplyToReviewAction): Saga {
185.   const errorHandler = createErrorHandler(errorHandlerId);
186. 
187.   yield put(errorHandler.createClearingAction());
188. 
189.   try {
190.     const state = yield select(getState);
191.     const reviewResponse: ExternalReviewReplyType = yield call(replyToReview, {
192.       apiState: state.api,
193.       body,
194.       originalReviewId,
195.       title,
196.     });
197. 
198.     yield put(setReviewReply({ originalReviewId, reply: reviewResponse }));
199. 
200.     yield put(hideReplyToReviewForm({ reviewId: originalReviewId }));
201.   } catch (error) {
202.     log.warn(`Failed to send reply to review ID ${originalReviewId}: ${error}`);
203.     yield put(errorHandler.createErrorAction(error));
204.   }
205. }
206. 
207. function* handleFlagReview({
208.   payload: { errorHandlerId, note, reason, reviewId },
209. }: FlagReviewAction): Saga {
210.   const errorHandler = createErrorHandler(errorHandlerId);
211. 
212.   yield put(errorHandler.createClearingAction());
213. 
214.   try {
215.     const state = yield select(getState);
216.     yield call(flagReview, {
217.       apiState: state.api,
218.       note,
219.       reason,
220.       reviewId,
221.     });
222. 
223.     yield put(setReviewWasFlagged({ reason, reviewId }));
224.   } catch (error) {
225.     log.warn(`Failed to flag review ID ${reviewId}: ${error}`);
226.     yield put(errorHandler.createErrorAction(error));
227.   }
228. }
229. 
230. function* manageAddonReview(
231.   action: CreateAddonReviewAction | UpdateAddonReviewAction,
232.   { _delay = delay }: Options = {},
233. ) {
234.   const { body, errorHandlerId, score } = action.payload;
235.   const errorHandler = createErrorHandler(errorHandlerId);
236. 
237.   const savingRating = !!score;
238.   const savingReview = !!body;
239. 
240.   yield put(errorHandler.createClearingAction());
241.   if (savingRating) {
242.     yield put(flashReviewMessage(STARTED_SAVE_RATING));
243.   }
244.   if (savingReview) {
245.     yield put(flashReviewMessage(STARTED_SAVE_REVIEW));
246.   }
247. 
248.   try {
249.     // $FlowIgnore: Flow can't tell what redux-saga's `select` returns.
250.     const state: AppState = yield select(getState);
251.     const baseParams = {
252.       apiState: state.api,
253.       body,
254.       score,
255.     };
256.     let params;
257. 
258.     let oldReview;
259.     if (action.type === CREATE_ADDON_REVIEW) {
260.       params = {
261.         ...baseParams,
262.         addonId: action.payload.addonId,
263.         versionId: action.payload.versionId,
264.       };
265.     } else if (action.type === UPDATE_ADDON_REVIEW) {
266.       params = {
267.         ...baseParams,
268.         reviewId: action.payload.reviewId,
269.       };
270.       oldReview = selectReview(state.reviews, action.payload.reviewId);
271.       invariant(
272.         oldReview,
273.         `review with ID=${action.payload.reviewId} does not exist in state`,
274.       );
275.     }
276.     invariant(
277.       params,
278.       `params was unexpectedly empty; action.type: ${action.type}`,
279.     );
280. 
281.     const submitParams: SubmitReviewParams = params;
282.     // $FlowIgnore: Flow can't tell what redux-saga's `call` returns.
283.     const reviewFromResponse: SubmitReviewResponse = yield call(
284.       submitReview,
285.       submitParams,
286.     );
287. 
288.     yield put(setReview(reviewFromResponse));
289. 
290.     if (savingRating) {
291.       yield put(flashReviewMessage(SAVED_RATING));
292.     }
293.     if (savingReview) {
294.       yield put(flashReviewMessage(SAVED_REVIEW));
295.       yield put(hideEditReviewForm({ reviewId: reviewFromResponse.id }));
296.     }
297. 
298.     if (!reviewFromResponse.is_developer_reply) {
299.       yield put(
300.         setLatestReview({
301.           addonId: reviewFromResponse.addon.id,
302.           review: reviewFromResponse,
303.           userId: reviewFromResponse.user.id,
304.         }),
305.       );
306. 
307.       yield put(
308.         updateRatingCounts({
309.           addonId: reviewFromResponse.addon.id,
310.           oldReview,
311.           newReview: createInternalReview(reviewFromResponse),
312.         }),
313.       );
314.     }
315. 
316.     // Make the message disappear after some time.
317.     yield _delay(FLASH_SAVED_MESSAGE_DURATION);
318.     yield put(hideFlashedReviewMessage());
319.   } catch (error) {
320.     log.warn(
321.       `Failed to create/update review with action ${action.type}: ${error}`,
322.     );
323.     yield put(errorHandler.createErrorAction(error));
324.     yield put(flashReviewMessage(ABORTED));
325.   }
326. }
327. 
328. function* deleteAddonReview({
329.   payload: { addonId, errorHandlerId, isReplyToReviewId, reviewId },
330. }: DeleteAddonReviewAction): Saga {
331.   const errorHandler = createErrorHandler(errorHandlerId);
332. 
333.   yield put(errorHandler.createClearingAction());
334. 
335.   try {
336.     const state = yield select(getState);
337.     yield call(deleteReview, {
338.       apiState: state.api,
339.       reviewId,
340.     });
341. 
342.     yield put(unloadAddonReviews({ addonId, reviewId }));
343.     if (isReplyToReviewId) {
344.       yield put(unloadAddonReviews({ addonId, reviewId: isReplyToReviewId }));
345.     }
346.   } catch (error) {
347.     log.warn(`Failed to delete review ID ${reviewId}: ${error}`);
348.     yield put(errorHandler.createErrorAction(error));
349.   }
350. }
351. 
352. function* fetchLatestUserReview({
353.   payload: { addonId, errorHandlerId, userId },
354. }: FetchLatestUserReviewAction): Saga {
355.   const errorHandler = createErrorHandler(errorHandlerId);
356. 
357.   yield put(errorHandler.createClearingAction());
358. 
359.   try {
360.     const state: AppState = yield select(getState);
361. 
362.     const params: GetLatestUserReviewParams = {
363.       addon: addonId,
364.       apiState: state.api,
365.       user: userId,
366.     };
367. 
368.     const review: GetLatestUserReviewResponse = yield call(
369.       getLatestUserReview,
370.       params,
371.     );
372. 
373.     const _setLatestReview = (value) => {
374.       return setLatestReview({
375.         userId,
376.         addonId,
377.         review: value,
378.       });
379.     };
380. 
381.     if (review) {
382.       yield put(setReview(review));
383.       yield put(_setLatestReview(review));
384.     } else {
385.       log.debug(
386.         `No saved review found for userId ${userId}, addonId ${addonId}`,
387.       );
388.       yield put(_setLatestReview(null));
389.     }
390.   } catch (error) {
391.     log.warn(
392.       `Failed to fetchLatestUserReview for addonId "${addonId}", userId "${userId}": ${error}`,
393.     );
394.     yield put(errorHandler.createErrorAction(error));
395.   }
396. }
397. 
398. function* fetchReview({
399.   payload: { errorHandlerId, reviewId },
400. }: FetchReviewAction): Saga {
401.   const errorHandler = createErrorHandler(errorHandlerId);
402. 
403.   yield put(errorHandler.createClearingAction());
404. 
405.   try {
406.     const state = yield select(getState);
407. 
408.     const params: GetReviewParams = {
409.       apiState: state.api,
410.       reviewId,
411.     };
412. 
413.     const review: ExternalReviewType = yield call(getReview, params);
414. 
415.     yield put(setReview(review));
416.   } catch (error) {
417.     log.warn(`Failed to get review ID ${reviewId}: ${error}`);
418.     yield put(errorHandler.createErrorAction(error));
419.   }
420. }
421. 
422. export default function* reviewsSaga(options?: Options): Saga {
423.   yield takeLatest(FETCH_LATEST_USER_REVIEW, fetchLatestUserReview);
424.   yield takeLatest(FETCH_REVIEW, fetchReview);
425.   yield takeLatest(FETCH_REVIEW_PERMISSIONS, fetchReviewPermissions);
426.   yield takeLatest(FETCH_REVIEWS, fetchReviews);
427.   yield takeLatest(FETCH_USER_REVIEWS, fetchUserReviews);
428.   yield takeLatest(SEND_REPLY_TO_REVIEW, handleReplyToReview);
429.   yield takeLatest(SEND_REVIEW_FLAG, handleFlagReview);
430.   yield takeLatest(CREATE_ADDON_REVIEW, (action) =>
431.     manageAddonReview(action, options),
432.   );
433.   yield takeLatest(UPDATE_ADDON_REVIEW, (action) =>
434.     manageAddonReview(action, options),
435.   );
436.   yield takeLatest(DELETE_ADDON_REVIEW, deleteAddonReview);
437. }
438.

