26. import * as siteApi from 'amo/api/site';
27. import siteReducer from 'amo/reducers/site';
28. import siteSaga from 'amo/sagas/site';
29. import FakeApp, { fakeAssets } from 'tests/unit/amo/server/fakeApp';
30. import {
31.   createUserAccountResponse,
32.   getFakeConfig,
33.   getFakeLogger,
34.   userAuthSessionId,
35. } from 'tests/unit/helpers_node';
36. 
37. function createStoreAndSagas({
38.   history = createHistory({ req: { url: '' } }),
39.   reducers = {
40.     api: apiReducer,
41.     site: siteReducer,
42.     users: usersReducer,
43.   },
44. } = {}) {
45.   const sagaMiddleware = createSagaMiddleware();
46.   const { createReduxHistory, routerMiddleware } = createReduxHistoryContext({
47.     history,
48.   });
49. 
50.   const store = configureStore({
51.     reducer: createRootReducer({ reducers }),
52.     // Do not define an initial state.
53.     preloadedState: undefined,
54.     middleware: (getDefaultMiddleware) =>
55.       getDefaultMiddleware().concat(
56.         middleware({
57.           routerMiddleware,
58.           sagaMiddleware,
59.         }),
60.       ),
61.   });
62. 
63.   return { connectedHistory: createReduxHistory(store), sagaMiddleware, store };
64. }
65. 
66. const StubApp = () => (
67.   <div>
68.     <Route path="*" component={FakeApp} />
69.   </div>
70. );
71. 
72. // This is an example of implementing a NotFound component
73. // using NestedStatus which exercises the server's logic for
74. // getting the response status code from the rendered component.
75. class NotFound extends React.Component {
76.   render() {
77.     return (
78.       <NestedStatus code={404}>
79.         <h1>Not Found</h1>
80.       </NestedStatus>
81.     );
82.   }
83. }
84. 
85. const NotFoundApp = () => (
86.   <div>
87.     <Route path="*" component={NotFound} />
88.   </div>
89. );
