94. export class ServerTestHelper {
95.   constructor() {
96.     this.helmetCanUseDOM = Helmet.canUseDOM;
97.     this.nestedStatusCanUseDOM = NestedStatus.canUseDOM;
98.     this.document = global.document;
99.   }
100. 
101.   beforeEach() {
102.     Helmet.canUseDOM = false;
103.     // See: https://github.com/gaearon/react-side-effect/releases/tag/v1.0.0
104.     // (`react-side-effect` is a dependency of `react-nested-status`).
105.     NestedStatus.canUseDOM = false;
106.     global.webpackIsomorphicTools = {
107.       assets: () => fakeAssets,
108.     };
109.     // We don't want the `document` object on the server.
110.     delete global.document;
111.   }
112. 
113.   afterEach() {
114.     Helmet.canUseDOM = this.helmetCanUseDOM;
115.     NestedStatus.canUseDOM = this.nestedStatusCanUseDOM;
116.     global.document = this.document;
117.     delete global.webpackIsomorphicTools;
118.   }
119. 
120.   testClient({
121.     App = StubApp,
122.     connectedHistory = null,
123.     store = null,
124.     sagaMiddleware = null,
125.     appSagas = null,
126.     config = defaultConfig,
127.     ...baseServerParams
128.   } = {}) {
129.     function _createStoreAndSagas({ history }) {
130.       if (store === null) {
131.         return createStoreAndSagas({ history });
132.       }
133. 
134.       return { connectedHistory, store, sagaMiddleware };
135.     }
